llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Psilocybin, a tryptamine with a tertiary aminoethyl side chain, has an absolute oral bioavailability of 52.7% in humans, showing that a similarly sized ionizable aminoethyl aromatic amine can achieve F well above 20% despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Psilocin, the active dephosphorylated form, has an absolute oral bioavailability of about 55% in humans, reinforcing that tryptamine-like tertiary amines are not inherently low-bioavailability compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Ziprasidone, a larger lipophilic amine with substantial first-pass metabolism, still reaches about 60% absolute oral bioavailability in the fed state, supporting high F for the query's moderately lipophilic ionizable amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "DMT has only 10-15% oral bioavailability, but this is due to MAO-mediated first-pass metabolism of the indoleethylamine; the query is an oxindole with a dipropylaminoethyl group and is not expected to share this MAO liability, so this contradictory evidence has low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The balance of transferable experimental evidence favors high oral bioavailability (F≥20%). Multiple human absolute-bioavailability measurements for structurally related tertiary-aminoethyl aromatic compounds (psilocybin/psilocin ~53-55%, ziprasidone ~60%) show F well above 20%. The only low-F analogue, DMT, owes its poor oral bioavailability to MAO metabolism of the indoleethylamine, a liability not shared by the query's oxindole-dipropylamine structure. The physicochemical prior is uncertain but does not outweigh these direct measurements.",
  "evidence_gaps": [
    "No direct human absolute bioavailability study for the query molecule.",
    "Morgan similarities of the evidence molecules are low (0.23-0.26), limiting transferability.",
    "Query-specific first-pass metabolism and permeability are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

